  "contradictory_card_ids": ["C51", "C95"],
  "prediction_basis_card_ids": ["C01", "C05", "C08", "C12"],
  "claims": [
    {
      "claim": "The query is an acrylamide-containing pyrazolopyrimidine BTK inhibitor; the most structurally relevant transferable L1 gold context, FK3453, shows low and unexpectedly poor human oral bioavailability attributed to AO-mediated clearance, supporting F<20%.",
      "card_ids": ["C01", "C05"]
    },
    {
      "claim": "Danavorexton, a lipophilic neutral piperidine amide with poor oral bioavailability requiring IV infusion, supports a low-F outcome for the query's lipophilic neutral piperidine amide/ether scaffold.",
      "card_ids": ["C08"]
    },
    {
      "claim": "Astemizole, a lipophilic piperidine drug, has estimated 3% oral bioavailability due to high presystemic elimination; the query's high logP and piperidine amide are consistent with extensive first-pass metabolism.",
      "card_ids": ["C12"]
    },
    {
      "claim": "L3 oral exposure records for related BTK inhibitors (rilzabrutinib, acalabrutinib) show rapid absorption and measurable Cmax/AUC, but do not provide affirmative F>=20% evidence for the query; the acalabrutinib IV comparator is ambiguous and not sufficient to overturn the low prediction.",
      "card_ids": ["C53", "C72", "C86", "C90", "C52", "C50", "C66", "C62", "C51", "C95"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C53", "C72", "C86", "C90", "C52", "C50", "C66", "C62", "C51", "C95", "C97", "C88", "C87", "C55"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule in the supplied records.",
    "L3 records provide oral exposure for related BTK inhibitors but not explicit F values; acalabrutinib IV comparator dose is ambiguous ('≤10 µg').",
    "Transfer from FK3453, danavorexton, and astemizole is based on structural/physicochemical analogy rather than identical scaffolds or matched conditions.",
    "The query's exact metabolic/clearance pathway (CYP vs AO) is not established from supplied evidence; FK3453's AO mechanism may not apply.",
    "Species differences (animal high F for FK3453) create uncertainty in human relevance."
  ],
  "decision_summary": "The query is an acrylamide-containing pyrazolopyrimidine BTK inhibitor (ibrutinib-like). Transferable L1 gold records (FK3453 human low, danavorexton poor, astemizole 3%) and the uniformly sub-20% L1 gold distribution support F<20%. L3 oral exposure records for related BTK inhibitors (rilzabrutinib, acalabrutinib) show rapid absorption and measurable Cmax/AUC but do not provide affirmative F>=20% evidence for the query; the acalabrutinib IV comparator is ambiguous and not sufficient to overturn. Prediction remains low with moderate confidence."
}

